import { memo, useDeferredValue, useEffect, useMemo, useState } from 'react';
import { CircleMarker, MapContainer, TileLayer, Tooltip as MapTooltip } from 'react-leaflet';
import {
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import simulation from '../utils/simulation_results.json';

// Generated by `npm run sync:simulation` from database/seed/simulation_results.json.
const { config, wards, scenarios, sensitivity } = simulation;

const POLICY_LABELS = {
  fcfs: 'First come, first served (status quo)',
  hybrid_fixed: 'Hybrid, weight fixed at 0.4',
  hybrid_gap: 'Hybrid, weight tuned on wait gap',
  hybrid_backlog: 'Hybrid, weight tuned on backlog count',
};
const COMPARED = ['hybrid_fixed', 'hybrid_gap', 'hybrid_backlog'];
const METRICS = {
  open: { label: 'Open requests per 10,000 people', unit: 'open per 10k' },
  wait: { label: 'Days to be served (past 7 days)', unit: 'days' },
};
const BOUNDS = [
  [Math.min(...wards.map((w) => w.lat)), Math.min(...wards.map((w) => w.lng))],
  [Math.max(...wards.map((w) => w.lat)), Math.max(...wards.map((w) => w.lng))],
];
const LEVEL = ['#e8f0ee', '#f2b705', '#8d2d2d'];
const BETTER = '#276749';
const WORSE = '#8d2d2d';
const NEUTRAL = '#f1f4f5';
const NO_DATA = '#c9d2d5';
const SPEEDS = { Slow: 400, Normal: 200, Fast: 80 };

const populationOf = Object.fromEntries(wards.map((w) => [w.id, w.population]));

function mix(from, to, t) {
  const a = parseInt(from.slice(1), 16);
  const b = parseInt(to.slice(1), 16);
  const channel = (shift) => Math.round(((a >> shift) & 255) * (1 - t) + ((b >> shift) & 255) * t);
  return `rgb(${channel(16)}, ${channel(8)}, ${channel(0)})`;
}

function levelColour(value, max) {
  if (value === null || value === undefined) return NO_DATA;
  const t = Math.min(value / max, 1);
  return t < 0.5 ? mix(LEVEL[0], LEVEL[1], t * 2) : mix(LEVEL[1], LEVEL[2], (t - 0.5) * 2);
}

function changeColour(diff, max) {
  if (diff === null) return NO_DATA;
  const t = Math.sqrt(Math.min(Math.abs(diff) / max, 1));
  return mix(NEUTRAL, diff < 0 ? BETTER : WORSE, t);
}

// One number per ward per day, for the chosen metric.
function wardValue(policy, metric, wardId, day) {
  if (metric === 'wait') return policy.ward_wait[wardId][day];
  const count = policy.ward_open[wardId][day];
  return count === null ? null : (count / populationOf[wardId]) * 10000;
}

function percentile95(values) {
  const sorted = values.filter((v) => v !== null).sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length * 0.95)] || 1;
}

const fixed = (value, digits = 2) => (value === null || value === undefined ? '-' : value.toFixed(digits));

const WardMap = memo(function WardMap({ title, subtitle, colourFor, valueText }) {
  return (
    <div className="sim-map-card">
      <h4>{title}</h4>
      <p className="sim-map-subtitle">{subtitle}</p>
      <MapContainer bounds={BOUNDS} boundsOptions={{ padding: [30, 30] }} scrollWheelZoom={false} className="sim-map">
        <TileLayer
          attribution="&copy; OpenStreetMap contributors"
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        {wards.map((ward) => {
          const deprived = ward.sampi_score >= config.deprived_sampi;
          return (
            <CircleMarker
              key={ward.id}
              center={[ward.lat, ward.lng]}
              radius={6 + Math.sqrt(ward.population) / 30}
              pathOptions={{
                color: deprived ? '#0d1f2d' : '#ffffff',
                weight: deprived ? 3 : 1.5,
                fillColor: colourFor(ward),
                fillOpacity: 0.9,
              }}
            >
              <MapTooltip>
                {ward.name}: {valueText(ward)}
                {deprived ? ' (deprived)' : ''}
              </MapTooltip>
            </CircleMarker>
          );
        })}
      </MapContainer>
    </div>
  );
});

function StatTile({ label, now, base, unit, digits = 1 }) {
  const diff = now !== null && base !== null ? now - base : null;
  return (
    <article className="stat-card stat-neutral">
      <p className="stat-label">{label}</p>
      <h3 className="stat-value">{fixed(now, digits)} <small>{unit}</small></h3>
      <p className="stat-hint">
        Status quo {fixed(base, digits)}
        {diff !== null && Math.abs(diff) >= 0.05 && (
          <span className={diff < 0 ? 'sim-delta-good' : 'sim-delta-bad'}>
            {' '}({diff > 0 ? '+' : ''}{diff.toFixed(digits)})
          </span>
        )}
      </p>
    </article>
  );
}

function SimulationPage() {
  const [scenarioKey, setScenarioKey] = useState('strained');
  const [policyKey, setPolicyKey] = useState('hybrid_gap');
  const [metric, setMetric] = useState('open');
  const [day, setDay] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [speed, setSpeed] = useState('Normal');

  // One timeout per day, so the last day can stop playback without a setState inside an updater.
  useEffect(() => {
    if (!playing) return undefined;
    const timer = setTimeout(() => {
      if (day >= config.days - 1) {
        setPlaying(false);
      } else {
        setDay(day + 1);
      }
    }, SPEEDS[speed]);
    return () => clearTimeout(timer);
  }, [playing, speed, day]);

  // The slider uses `day` so it stays responsive. Maps and charts follow `shownDay`, which React may lag behind.
  const shownDay = useDeferredValue(day);
  const policies = scenarios[scenarioKey].policies;
  const status = policies.fcfs;
  const chosen = policies[policyKey];
  const week = Math.floor(day / 7) + 1;
  const algorithmOn = shownDay >= config.switch_day;
  const shown = algorithmOn ? chosen : status;

  const { levelMax, changeMax } = useMemo(() => {
    const levels = [];
    const changes = [];
    for (let d = 0; d < config.days; d += 1) {
      wards.forEach((w) => {
        levels.push(wardValue(status, metric, w.id, d));
        const a = wardValue(chosen, metric, w.id, d);
        const b = wardValue(status, metric, w.id, d);
        if (a !== null && b !== null) changes.push(Math.abs(a - b));
      });
    }
    return { levelMax: percentile95(levels), changeMax: percentile95(changes) };
  }, [status, chosen, metric]);

  const chartRows = useMemo(
    () => Array.from({ length: config.days }, (_, i) => ({
      day: i + 1,
      statusDeprived: status.wait_deprived[i],
      statusAffluent: status.wait_affluent[i],
      deprived: chosen.wait_deprived[i],
      affluent: chosen.wait_affluent[i],
      openStatusDeprived: status.backlog_deprived[i],
      openStatusAffluent: status.backlog_affluent[i],
      openDeprived: chosen.backlog_deprived[i],
      openAffluent: chosen.backlog_affluent[i],
      alpha: chosen.alpha[i],
    })),
    [chosen, status],
  );

  const row = chartRows[shownDay];
  const sensitivityRows = useMemo(
    () => sensitivity.map((item) => ({
      label: `${item.arrivals_per_day} reports/day, reporting bias ${item.reporting_bias}`,
      cells: ['fcfs', ...COMPARED].map((key) => item.policies[key]),
    })),
    [],
  );

  const summary = (key) => policies[key].summary_last_4_weeks;
  const unit = METRICS[metric].unit;

  return (
    <section className="stack-panel">
      <div className="sim-banner" role="note">
        <strong>Simulation on synthetic data.</strong> Ward scores and populations are illustrative. Arrivals, crew
        hours and where crews are based are assumptions. It shows who gets served first, not repairs to infrastructure.
      </div>

      <article className="panel-card">
        <div className="sim-controls">
          <label className="sim-field">
            City conditions
            <select className="select-input" value={scenarioKey} onChange={(e) => setScenarioKey(e.target.value)}>
              {Object.entries(scenarios).map(([key, value]) => (
                <option key={key} value={key}>{value.label} ({value.arrivals_per_day} reports a day)</option>
              ))}
            </select>
          </label>
          <label className="sim-field">
            Compare the status quo with
            <select className="select-input" value={policyKey} onChange={(e) => setPolicyKey(e.target.value)}>
              {COMPARED.map((key) => <option key={key} value={key}>{POLICY_LABELS[key]}</option>)}
            </select>
          </label>
          <label className="sim-field">
            Map shows
            <select className="select-input" value={metric} onChange={(e) => setMetric(e.target.value)}>
              {Object.entries(METRICS).map(([key, value]) => <option key={key} value={key}>{value.label}</option>)}
            </select>
          </label>
          <button type="button" className="primary-btn" onClick={() => {
            if (day >= config.days - 1) setDay(0);
            setPlaying((p) => !p);
          }}
          >
            {playing ? 'Pause' : 'Play'}
          </button>
          <label className="sim-field">
            Speed
            <select className="select-input" value={speed} onChange={(e) => setSpeed(e.target.value)}>
              {Object.keys(SPEEDS).map((name) => <option key={name}>{name}</option>)}
            </select>
          </label>
        </div>

        <div className="sim-slider">
          <input
            type="range"
            min="0"
            max={config.days - 1}
            value={day}
            onChange={(e) => { setPlaying(false); setDay(Number(e.target.value)); }}
            aria-label="Simulated day"
          />
          <p>
            Week {week}, day {day + 1} of {config.days}
            <span className={algorithmOn ? 'sim-tag sim-tag-on' : 'sim-tag'}>
              {algorithmOn ? 'Algorithm on' : 'Status quo'}
            </span>
          </p>
        </div>

        <div className="page-grid page-grid-four">
          <StatTile label="Deprived wards: days to be served" now={algorithmOn ? row.deprived : row.statusDeprived} base={row.statusDeprived} unit="days" />
          <StatTile label="Affluent wards: days to be served" now={algorithmOn ? row.affluent : row.statusAffluent} base={row.statusAffluent} unit="days" />
          <StatTile label="Deprived wards: open requests" now={algorithmOn ? row.openDeprived : row.openStatusDeprived} base={row.openStatusDeprived} unit="open" digits={0} />
          <StatTile label="Affluent wards: open requests" now={algorithmOn ? row.openAffluent : row.openStatusAffluent} base={row.openStatusAffluent} unit="open" digits={0} />
        </div>

        <div className="sim-maps">
          <WardMap
            title="Status quo: first come, first served"
            subtitle={METRICS[metric].label}
            colourFor={(w) => levelColour(wardValue(status, metric, w.id, shownDay), levelMax)}
            valueText={(w) => {
              const v = wardValue(status, metric, w.id, shownDay);
              return v === null ? 'no data' : `${v.toFixed(1)} ${unit}`;
            }}
          />
          <WardMap
            title={`Change with: ${POLICY_LABELS[policyKey]}`}
            subtitle={algorithmOn ? 'Green is better than the status quo, red is worse' : 'No change until the algorithm switches on in week 5'}
            colourFor={(w) => {
              const a = wardValue(shown, metric, w.id, shownDay);
              const b = wardValue(status, metric, w.id, shownDay);
              return changeColour(a === null || b === null ? null : a - b, changeMax);
            }}
            valueText={(w) => {
              const a = wardValue(shown, metric, w.id, shownDay);
              const b = wardValue(status, metric, w.id, shownDay);
              if (a === null || b === null) return 'no data';
              const d = a - b;
              return `${d > 0 ? '+' : ''}${d.toFixed(1)} ${unit}`;
            }}
          />
        </div>

        <div className="sim-legend">
          <span>Left</span>
          <span className="sim-gradient" />
          <span>low to {levelMax.toFixed(1)}+ {unit}</span>
          <span>Right</span>
          <span className="sim-gradient sim-gradient-change" />
          <span>better to worse, up to {changeMax.toFixed(1)} {unit}</span>
          <span>Dark outline: deprived ward (SAMPI 0.5 or above). Size: population.</span>
        </div>
      </article>

      <div className="chart-grid">
        <article className="chart-card">
          <h3>Days to be served, deprived versus affluent</h3>
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={chartRows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="day" label={{ value: 'day', position: 'insideBottom', offset: -2 }} />
              <YAxis />
              <Tooltip formatter={(value) => (value === null ? '-' : Number(value).toFixed(2))} />
              <Legend />
              <ReferenceLine x={config.switch_day + 1} stroke="#5c6f75" strokeDasharray="4 4" label="Algorithm on" />
              <ReferenceLine x={shownDay + 1} stroke="#165d5a" />
              <Line isAnimationActive={false} dataKey="statusDeprived" name="Deprived, status quo" stroke="#8d2d2d" strokeDasharray="5 4" dot={false} />
              <Line isAnimationActive={false} dataKey="statusAffluent" name="Affluent, status quo" stroke="#1d3557" strokeDasharray="5 4" dot={false} />
              <Line isAnimationActive={false} dataKey="deprived" name="Deprived, with algorithm" stroke="#8d2d2d" strokeWidth={2} dot={false} />
              <Line isAnimationActive={false} dataKey="affluent" name="Affluent, with algorithm" stroke="#1d3557" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
          <p className="panel-subtitle">Counts only requests already served, so it can hide a growing queue. Read it with the chart on the right.</p>
        </article>

        <article className="chart-card">
          <h3>Open requests, deprived versus affluent</h3>
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={chartRows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="day" />
              <YAxis />
              <Tooltip formatter={(value) => (value === null ? '-' : Number(value).toFixed(0))} />
              <Legend />
              <ReferenceLine x={config.switch_day + 1} stroke="#5c6f75" strokeDasharray="4 4" />
              <ReferenceLine x={shownDay + 1} stroke="#165d5a" />
              <Line isAnimationActive={false} dataKey="openStatusDeprived" name="Deprived, status quo" stroke="#8d2d2d" strokeDasharray="5 4" dot={false} />
              <Line isAnimationActive={false} dataKey="openStatusAffluent" name="Affluent, status quo" stroke="#1d3557" strokeDasharray="5 4" dot={false} />
              <Line isAnimationActive={false} dataKey="openDeprived" name="Deprived, with algorithm" stroke="#8d2d2d" strokeWidth={2} dot={false} />
              <Line isAnimationActive={false} dataKey="openAffluent" name="Affluent, with algorithm" stroke="#1d3557" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
          <p className="panel-subtitle">Requests waiting for a crew at the end of each day.</p>
        </article>

        <article className="chart-card chart-card-wide">
          <h3>Equity weight (alpha) over time</h3>
          <ResponsiveContainer width="100%" height={220}>
            <LineChart data={chartRows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="day" />
              <YAxis domain={[0, 1]} />
              <Tooltip formatter={(value) => (value === null ? '-' : Number(value).toFixed(2))} />
              <ReferenceLine x={config.switch_day + 1} stroke="#5c6f75" strokeDasharray="4 4" />
              <ReferenceLine x={shownDay + 1} stroke="#165d5a" />
              <Line isAnimationActive={false} dataKey="alpha" name="alpha" stroke="#165d5a" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </article>
      </div>

      <article className="panel-card">
        <h3>Weeks 9 to 12, {scenarios[scenarioKey].label.toLowerCase()}</h3>
        <div className="table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>Policy</th>
                <th>Days served, deprived</th>
                <th>Days served, affluent</th>
                <th>Open, deprived</th>
                <th>Open, affluent</th>
                <th>Final alpha</th>
              </tr>
            </thead>
            <tbody>
              {Object.keys(POLICY_LABELS).map((key) => (
                <tr key={key}>
                  <td>{POLICY_LABELS[key]}</td>
                  <td>{fixed(summary(key).wait_deprived_days.mean)}</td>
                  <td>{fixed(summary(key).wait_affluent_days.mean)}</td>
                  <td>{fixed(summary(key).backlog_deprived.mean, 0)}</td>
                  <td>{fixed(summary(key).backlog_affluent.mean, 0)}</td>
                  <td>{fixed(summary(key).alpha.mean)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p className="panel-subtitle">
          Average of {config.seeds} runs on identical request streams. Prioritising moves waiting time between
          groups. It cannot create crew capacity, so helping one group can leave the other with a longer queue.
        </p>
      </article>

      <article className="panel-card">
        <h3>Does it hold up? Weeks 9 to 12 across nine settings</h3>
        <div className="table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>Setting</th>
                <th>Status quo</th>
                <th>Fixed 0.4</th>
                <th>Tuned on wait gap</th>
                <th>Tuned on backlog</th>
              </tr>
            </thead>
            <tbody>
              {sensitivityRows.map((item) => (
                <tr key={item.label}>
                  <td>{item.label}</td>
                  {item.cells.map((cell, i) => {
                    const gap = cell.wait_deprived_days - cell.wait_affluent_days;
                    return (
                      <td key={i}>
                        {gap > 0 ? '+' : ''}{gap.toFixed(2)} d gap<br />
                        <small>open {cell.open_deprived.toFixed(0)} / {cell.open_affluent.toFixed(0)}</small>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p className="panel-subtitle">
          Gap is days served for deprived wards minus affluent wards; positive means deprived wards wait longer.
          Open is deprived / affluent requests still waiting. A fixed weight clears deprived queues but can leave
          affluent queues much longer. Tuning on the wait gap keeps the two closer, while tuning on report counts
          tended to leave deprived wards waiting longer in these runs.
        </p>
      </article>
    </section>
  );
}

export default SimulationPage;
